CREATE TABLE IF NOT EXISTS local_profiles (id TEXT PRIMARY KEY, locale TEXT NOT NULL, time_zone TEXT NOT NULL, day_boundary TEXT NOT NULL DEFAULT '04:00', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS final_bosses (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES local_profiles(id), name TEXT NOT NULL, motivation TEXT, target_date TEXT, cover_color TEXT NOT NULL DEFAULT '#62E5E0', status TEXT NOT NULL CHECK(status IN ('draft','active','defeated','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_boss ON final_bosses(profile_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS milestones (id TEXT PRIMARY KEY, boss_id TEXT NOT NULL REFERENCES final_bosses(id), name TEXT NOT NULL, note TEXT, target_date TEXT, sort_order INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('not_started','in_progress','complete')), completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quest_templates (id TEXT PRIMARY KEY, boss_id TEXT REFERENCES final_bosses(id), milestone_id TEXT REFERENCES milestones(id), kind TEXT NOT NULL CHECK(kind IN ('habit','task')), title TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')), target_intensity REAL, minimum_win REAL, unit TEXT, proof_rule TEXT NOT NULL CHECK(proof_rule IN ('not_needed','optional','required')), notes TEXT, recurrence TEXT, reminder_enabled INTEGER NOT NULL DEFAULT 1, archived_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS occurrences (id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES quest_templates(id), local_date TEXT NOT NULL, start_time TEXT, deadline_time TEXT, time_zone TEXT NOT NULL, state TEXT NOT NULL, title_snapshot TEXT NOT NULL, priority_snapshot TEXT NOT NULL, target_snapshot REAL, minimum_win_snapshot REAL, unit_snapshot TEXT, proof_rule_snapshot TEXT NOT NULL, milestone_snapshot TEXT, user_order INTEGER NOT NULL DEFAULT 0, started_at TEXT, rescheduled_from TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(template_id, local_date));
CREATE INDEX IF NOT EXISTS occurrence_date_idx ON occurrences(local_date);
CREATE TABLE IF NOT EXISTS completions (id TEXT PRIMARY KEY, occurrence_id TEXT NOT NULL UNIQUE REFERENCES occurrences(id), outcome TEXT NOT NULL CHECK(outcome IN ('complete','partial','skipped')), actual_intensity REAL, note TEXT, calculation_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proof_assets (id TEXT PRIMARY KEY, completion_id TEXT REFERENCES completions(id), original_path TEXT NOT NULL, thumbnail_path TEXT NOT NULL, media_type TEXT NOT NULL, byte_size INTEGER NOT NULL, checksum TEXT NOT NULL, save_state TEXT NOT NULL, alt_text TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS xp_ledger (id TEXT PRIMARY KEY, completion_id TEXT NOT NULL REFERENCES completions(id), base INTEGER NOT NULL, factor REAL NOT NULL, delta INTEGER NOT NULL, calculation_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (profile_id TEXT PRIMARY KEY REFERENCES local_profiles(id), plain_language INTEGER NOT NULL DEFAULT 0, reduced_motion INTEGER NOT NULL DEFAULT 0, sound_enabled INTEGER NOT NULL DEFAULT 0, haptics_enabled INTEGER NOT NULL DEFAULT 1, privacy_shield INTEGER NOT NULL DEFAULT 1, notifications_enabled INTEGER NOT NULL DEFAULT 0, quiet_start TEXT NOT NULL DEFAULT '21:00', quiet_end TEXT NOT NULL DEFAULT '07:00', daily_capacity_minutes INTEGER NOT NULL DEFAULT 180, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reminders (id TEXT PRIMARY KEY, occurrence_id TEXT NOT NULL REFERENCES occurrences(id), notification_id TEXT, stage TEXT NOT NULL, trigger_at TEXT NOT NULL, state TEXT NOT NULL, cancellation_reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_reflections (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES local_profiles(id), local_date TEXT NOT NULL, text TEXT, load_realistic INTEGER, created_at TEXT NOT NULL, UNIQUE(profile_id, local_date));
CREATE TABLE IF NOT EXISTS voyages (id TEXT PRIMARY KEY, boss_id TEXT NOT NULL REFERENCES final_bosses(id), boss_name_snapshot TEXT NOT NULL, motivation_snapshot TEXT, summary_json TEXT NOT NULL, reflection TEXT, final_state TEXT NOT NULL CHECK(final_state IN ('defeated','archived')), started_at TEXT NOT NULL, completed_at TEXT NOT NULL);
PRAGMA user_version = 1;
